def lucas_memo(n, memo=None):
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n == 0:
        return 2
    if n == 1:
        return 1
    memo[n] = lucas_memo(n - 1, memo) + lucas_memo(n - 2, memo)
    return memo[n]
