def max_points_with_duplicates(nums):
    counts = {}
    for n in nums:
        counts[n] = counts.get(n, 0) + 1
    if not counts:
        return 0
    dp = [0] * (max(counts) + 2)
    for v in sorted(counts):
        dp[v] = max(dp[v], dp[v - 1] + v * counts[v])
        dp[v + 1] = max(dp[v + 1], dp[v - 1] + v * counts[v])
    return dp[-1]
